import { describe, it } from 'vitest';

describe('REQ-006 Separate services', () => {
  it.todo('REQ-006 AC1: manual: Running the API server and the live update server as separate processes or deployments is a deployment topology property that cannot be verified through the HTTP routes.');

  it.todo('REQ-006 AC2: manual: Starting, stopping and deploying each service without redeploying the other requires operating the separate deployments, which is not testable through the HTTP routes.');
});

import { describe, expect, it } from 'vitest';
import request from 'supertest';
import { createApp } from '../src/app/app.js';

type App = ReturnType<typeof createApp>;

async function registerSeller(app: App, displayName: string): Promise<string> {
  const res = await request(app).post('/api/users').send({ displayName });
  return res.body.id as string;
}

const FUTURE_END = '2099-01-01T00:00:00.000Z';

describe('UC-002 List item', () => {
  it('REQ-001 AC1: A seller can submit an item with a starting price, an end time and a currency (CHF, EUR or USD) and it then appears as an open auction.', async () => {
    const app = createApp();
    const sellerId = await registerSeller(app, 'Seller One');

    const created = await request(app).post('/api/items').send({
      userId: sellerId,
      title: 'Vintage clock',
      startingPrice: 100,
      endTime: FUTURE_END,
      currency: 'CHF',
    });
    expect(created.status).toBe(201);

    const listed = await request(app).get('/api/items');
    expect(listed.status).toBe(200);
    const match = (listed.body as Array<{ sellerId: string; status: string; currency: string }>).find(
      (item) => item.sellerId === sellerId,
    );
    expect(match).toBeDefined();
    expect(match?.status).toBe('open');
    expect(match?.currency).toBe('CHF');
  });

  it('REQ-001 AC2: A listing without a starting price, end time or currency is rejected with an error message.', async () => {
    const app = createApp();
    const sellerId = await registerSeller(app, 'Seller Two');

    const res = await request(app).post('/api/items').send({
      userId: sellerId,
      title: 'Incomplete listing',
    });
    expect(res.status).toBe(400);
    expect(typeof res.body.error).toBe('string');
    expect(res.body.error.length).toBeGreaterThan(0);
  });

  it('REQ-001 AC3: A listing with a currency other than CHF, EUR or USD is rejected.', async () => {
    const app = createApp();
    const sellerId = await registerSeller(app, 'Seller Three');

    const res = await request(app).post('/api/items').send({
      userId: sellerId,
      title: 'Bicycle',
      startingPrice: 50,
      endTime: FUTURE_END,
      currency: 'GBP',
    });
    expect(res.status).toBe(400);
    expect(res.body).toHaveProperty('error');
  });

  it('SEQ-002 scenario: List item', async () => {
    const app = createApp();

    const userRes = await request(app).post('/api/users').send({ displayName: 'Seller Four' });
    expect(userRes.status).toBe(201);
    const sellerId = userRes.body.id as string;

    const itemRes = await request(app).post('/api/items').send({
      userId: sellerId,
      title: 'Bookshelf',
      startingPrice: 75,
      endTime: FUTURE_END,
      currency: 'EUR',
    });
    expect(itemRes.status).toBe(201);
    expect(itemRes.body.sellerId).toBe(sellerId);
    expect(itemRes.body.currency).toBe('EUR');
    expect(itemRes.body.status).toBe('open');
  });
});

