import { describe, expect, it } from 'vitest';
import { LiveGateway } from '../src/live-updates/LiveGateway.js';
import { EventFeedClient } from '../src/live-updates/EventFeedClient.js';

function setup() {
  const sent: string[] = [];
  const socket = { send: (message: string) => { sent.push(message); } } as unknown as WebSocket;
  const sockets = new Map<string, WebSocket>();
  sockets.set('client-1', socket);
  const liveGateway = new LiveGateway(sockets);
  const eventFeedClient = new EventFeedClient(liveGateway);
  return { sent, liveGateway, eventFeedClient };
}

describe('UC-004 Watch item live', () => {
  it.todo('REQ-007 AC1: manual: requires deploying two or more live update server instances and a multi-instance load setup, not practical as a unit test');

  it.todo('REQ-007 AC2: manual: requires deploying an additional instance and verifying no code change, a deployment-level check');

  it('SEQ-004 scenario: Watch item live', () => {
    const { sent, liveGateway, eventFeedClient } = setup();
    const payload = JSON.stringify({ itemId: 'item-1', amount: 25 });

    liveGateway.watch('client-1', 'item-1');
    eventFeedClient.onEvent('bid.accepted', payload);

    expect(sent.length).toBe(1);
    expect(sent[0]).toContain(payload);

    liveGateway.unwatch('client-1', 'item-1');
  });
});

import { describe, expect, it, vi } from 'vitest';
import { Item } from '../src/auction-api/Item.js';
import { BidController } from '../src/auction-api/BidController.js';
import { BidService } from '../src/auction-api/BidService.js';
import { ItemStore } from '../src/auction-api/ItemStore.js';
import { UserStore } from '../src/auction-api/UserStore.js';
import { BidEventPublisher } from '../src/auction-api/BidEventPublisher.js';
import { EventFeed } from '../src/auction-api/EventFeed.js';
import { LiveGateway } from '../src/live-updates/LiveGateway.js';
import { EventFeedClient } from '../src/live-updates/EventFeedClient.js';

const FAR_FUTURE = new Date('2100-01-01T00:00:00.000Z');
const PAST = new Date('2000-01-01T00:00:00.000Z');
const TWO_MINUTES_MS = 2 * 60 * 1000;

function makeItem(overrides: Partial<{ id: string; sellerId: string; startingPrice: number; endTime: Date; highestBidAmount: number | null; highestBidderId: string | null }> = {}): Item {
  return new Item(
    overrides.id ?? 'item-1',
    overrides.sellerId ?? 'seller-1',
    'Lamp',
    overrides.startingPrice ?? 50,
    'USD' as Item['currency'],
    overrides.endTime ?? FAR_FUTURE,
    'open' as Item['status'],
    overrides.highestBidAmount ?? null,
    overrides.highestBidderId ?? null,
    null,
  );
}

function fakeStores(items: Item[], userIds: string[]) {
  const itemMap = new Map<string, Item>();
  for (const item of items) itemMap.set(item.id, item);
  const users = new Set(userIds);
  const bids: unknown[] = [];
  const itemStore = {
    findItem: async (id: string) => itemMap.get(id) ?? null,
    saveItem: async (item: Item) => {
      itemMap.set(item.id, item);
      return item;
    },
    saveBid: async (bid: unknown) => {
      bids.push(bid);
      return bid;
    },
  } as unknown as ItemStore;
  const userStore = {
    findById: async (id: string) => (users.has(id) ? { id } : null),
  } as unknown as UserStore;
  return { itemStore, userStore, bids };
}

function makeService(items: Item[], userIds: string[] = ['bidder-1', 'bidder-2']) {
  const stores = fakeStores(items, userIds);
  const eventFeed = { publish: vi.fn() } as unknown as EventFeed;
  const publisher = new BidEventPublisher(eventFeed);
  const service = new BidService(stores.itemStore, publisher, stores.userStore);
  return { service, bids: stores.bids, eventFeed };
}

function makeGateway() {
  const sockets = new Map<string, { readyState: number; send: ReturnType<typeof vi.fn> }>();
  const gateway = new LiveGateway(sockets as unknown as ConstructorParameters<typeof LiveGateway>[0]);
  return { gateway, sockets };
}

function addSocket(sockets: Map<string, { readyState: number; send: ReturnType<typeof vi.fn> }>, clientId: string) {
  const socket = { readyState: 1, send: vi.fn() };
  sockets.set(clientId, socket);
  return socket;
}

describe('UC-003 Place bid', () => {
  it("REQ-002 AC1: A bid on an item whose end time has not passed, from a user other than the seller, is stored in the item currency if it is valid.", async () => {
    const { service, bids } = makeService([makeItem()]);
    const bid = await service.placeBid('item-1', 'bidder-1', 60);
    expect(bid.amount).toBe(60);
    expect(bid.bidderId).toBe('bidder-1');
    expect(bids).toHaveLength(1);
  });

  it("REQ-002 AC2: A bid on an item whose end time has passed is rejected.", async () => {
    const { service, bids } = makeService([makeItem({ endTime: PAST })]);
    await expect(service.placeBid('item-1', 'bidder-1', 60)).rejects.toThrow();
    expect(bids).toHaveLength(0);
  });

  it("REQ-002 AC3: The first bid is accepted only if it is at least the starting price.", async () => {
    const { service } = makeService([makeItem({ startingPrice: 50 })]);
    await expect(service.placeBid('item-1', 'bidder-1', 49)).rejects.toThrow();
  });

  it("REQ-002 AC4: Any later bid is accepted only if it is at least 1 unit of the item currency higher than the current highest bid, otherwise it is rejected.", async () => {
    const { service } = makeService([makeItem({ startingPrice: 50 })]);
    await service.placeBid('item-1', 'bidder-1', 100);
    await expect(service.placeBid('item-1', 'bidder-2', 100)).rejects.toThrow();
  });

  it("REQ-002 AC5: A bid by the item's seller on their own item is rejected.", async () => {
    const { service, bids } = makeService([makeItem({ sellerId: 'seller-1' })], ['seller-1']);
    await expect(service.placeBid('item-1', 'seller-1', 60)).rejects.toThrow();
    expect(bids).toHaveLength(0);
  });

  it("REQ-009 AC1: A valid bid placed less than or exactly 2 minutes before the end time moves the end time 2 minutes later.", () => {
    const now = new Date('2030-01-01T12:00:00.000Z');
    const endTime = new Date(now.getTime() + TWO_MINUTES_MS);
    const item = makeItem({ endTime });
    const extended = item.extendIfLate(now);
    expect(extended).toBe(true);
    expect(item.endTime.getTime()).toBe(endTime.getTime() + TWO_MINUTES_MS);
  });

  it("REQ-009 AC2: A valid bid placed more than 2 minutes before the end time does not change the end time.", () => {
    const now = new Date('2030-01-01T12:00:00.000Z');
    const endTime = new Date(now.getTime() + TWO_MINUTES_MS + 60 * 1000);
    const item = makeItem({ endTime });
    const extended = item.extendIfLate(now);
    expect(extended).toBe(false);
    expect(item.endTime.getTime()).toBe(endTime.getTime());
  });

  it.todo('REQ-009 AC3: manual: watchers seeing the new end time without reloading needs a real browser session');

  it("REQ-003 AC1: When a bid is accepted, every client watching the item shows the new bid without a page reload.", () => {
    const { gateway, sockets } = makeGateway();
    const first = addSocket(sockets, 'client-1');
    const second = addSocket(sockets, 'client-2');
    gateway.watch('client-1', 'item-1');
    gateway.watch('client-2', 'item-1');
    gateway.broadcast('item-1', 'bid 60 on item-1');
    expect(first.send).toHaveBeenCalledWith(expect.stringContaining('bid 60 on item-1'));
    expect(second.send).toHaveBeenCalledWith(expect.stringContaining('bid 60 on item-1'));
  });

  it("REQ-003 AC2: A client watching a different item does not receive that bid.", () => {
    const { gateway, sockets } = makeGateway();
    const other = addSocket(sockets, 'client-1');
    gateway.watch('client-1', 'item-2');
    gateway.broadcast('item-1', 'bid 60 on item-1');
    expect(other.send).not.toHaveBeenCalled();
  });

  it.todo('REQ-011 AC1: manual: 200 concurrent watchers with a 1 second delivery bound needs a dedicated load environment');

  it.todo('REQ-011 AC2: manual: no lost bids under sustained load needs a dedicated load environment');

  it("SEQ-003 scenario: Place bid", async () => {
    const item = makeItem();
    const stores = fakeStores([item], ['bidder-1']);
    const eventFeed = { publish: vi.fn() } as unknown as EventFeed;
    const publisher = new BidEventPublisher(eventFeed);
    const service = new BidService(stores.itemStore, publisher, stores.userStore);
    const controller = new BidController(service);
    const bid = await controller.placeBid('item-1', 'bidder-1', 60);
    expect(bid.amount).toBe(60);
    expect(stores.bids).toHaveLength(1);
    expect(eventFeed.publish).toHaveBeenCalledWith(expect.any(String), expect.any(String));
    expect(EventFeedClient).toBeDefined();
  });
});

import { describe, expect, it } from 'vitest';
import { DatabaseSync } from 'node:sqlite';
import { AuctionStatus } from '../src/auction-api/AuctionStatus.js';
import { Item } from '../src/auction-api/Item.js';
import { ItemStore } from '../src/auction-api/ItemStore.js';
import { ItemService } from '../src/auction-api/ItemService.js';
import { AuctionEventPublisher } from '../src/auction-api/AuctionEventPublisher.js';
import { AuctionCloser } from '../src/auction-api/AuctionCloser.js';

const endTime = new Date('2030-01-01T00:00:00Z');

function capturingFeed() {
  const published: Array<{ topic: string; payload: string }> = [];
  const feed = {
    publish(topic: string, payload: string) {
      published.push({ topic, payload });
    },
  };
  return { feed, published };
}

function setup() {
  const db = new DatabaseSync(':memory:');
  const itemStore = new ItemStore(db);
  const { feed, published } = capturingFeed();
  const publisher = new AuctionEventPublisher(feed as never);
  const itemService = new ItemService(itemStore, undefined as never, publisher);
  return { itemStore, itemService, published };
}

function openItem(id: string, highestBidderId: string | null, highestBidAmount: number | null) {
  return new Item(
    id,
    'seller-1',
    'Vintage lamp',
    10,
    'USD' as never,
    endTime,
    AuctionStatus.open,
    highestBidAmount,
    highestBidderId,
    null,
  );
}

describe('UC-005 Close auction', () => {
  it('REQ-004 AC1: At the end time the item no longer accepts bids.', async () => {
    const { itemStore, itemService } = setup();
    const item = openItem('item-1', 'bidder-1', 20);
    expect(item.isOpen(endTime)).toBe(false);
    await itemStore.saveItem(item);
    await itemService.closeDueAuctions(endTime);
    const stored = await itemStore.findItem('item-1');
    expect(stored).not.toBeNull();
    expect(stored!.status).not.toBe(AuctionStatus.open);
  });

  it('REQ-004 AC2: The bidder with the highest bid at the end time is recorded as the winner and the winning user sees on the item page that they won.', async () => {
    const { itemStore, itemService } = setup();
    await itemStore.saveItem(openItem('item-2', 'bidder-7', 50));
    await itemService.closeDueAuctions(endTime);
    const stored = await itemService.getItem('item-2');
    expect(stored.winnerId).toBe('bidder-7');
    expect(stored.status).toBe(AuctionStatus.closed);
  });

  it('REQ-004 AC3: Watchers of the item see the closed state and the winner.', async () => {
    const { itemStore, itemService, published } = setup();
    await itemStore.saveItem(openItem('item-3', 'bidder-9', 40));
    await itemService.closeDueAuctions(endTime);
    const closedEvent = published.find((e) => e.payload.includes('item-3'));
    expect(closedEvent).toBeDefined();
    expect(closedEvent!.payload).toContain('closed');
    expect(closedEvent!.payload).toContain('bidder-9');
  });

  it('REQ-004 AC4: An auction that ends with no bids is shown as unsold and has no winner.', async () => {
    const { itemStore, itemService } = setup();
    await itemStore.saveItem(openItem('item-4', null, null));
    await itemService.closeDueAuctions(endTime);
    const stored = await itemService.getItem('item-4');
    expect(stored.status).toBe(AuctionStatus.unsold);
    expect(stored.winnerId).toBeNull();
  });

  it('SEQ-005 scenario: Close auction', async () => {
    const { itemStore, itemService, published } = setup();
    await itemStore.saveItem(openItem('item-5', 'bidder-3', 30));
    const closer = new AuctionCloser(itemService, 1000);
    await closer.tick();
    const stored = await itemStore.findItem('item-5');
    expect(stored!.status).toBe(AuctionStatus.closed);
    expect(stored!.winnerId).toBe('bidder-3');
    expect(published.some((e) => e.payload.includes('item-5'))).toBe(true);
  });
});

import { afterEach, describe, expect, it, vi } from 'vitest';
import { Currency } from '../src/auction-api/Currency.js';
import { ItemController } from '../src/auction-api/ItemController.js';
import { ItemService } from '../src/auction-api/ItemService.js';
import { ExchangeRateService } from '../src/exchange-rates/ExchangeRateService.js';
import { FrankfurterClient } from '../src/exchange-rates/FrankfurterClient.js';

const ONE_HOUR_MS = 60 * 60 * 1000;

afterEach(() => {
  vi.restoreAllMocks();
  vi.useRealTimers();
});

function makeItem(): Record<string, unknown> {
  return {
    id: 'item-1',
    title: 'Vintage clock',
    startingPrice: 100,
    highestBid: 150,
    currency: 'CHF',
    endTime: '2030-01-01T00:00:00.000Z',
    status: 'open',
  };
}

function makeItemService(item: Record<string, unknown>): ItemService {
  return {
    getItem: vi.fn(async () => item),
    listItem: vi.fn(async () => item),
    listOpenItems: vi.fn(async () => [item]),
    closeDueAuctions: vi.fn(async () => undefined),
  } as unknown as ItemService;
}

function makeRates(): Record<string, number> {
  return { CHF: 1, EUR: 0.9, USD: 1.1 };
}

function makeSetup(ttlMs: number = ONE_HOUR_MS) {
  const client = new FrankfurterClient();
  const fetchSpy = vi.spyOn(client, 'fetchRates').mockResolvedValue(makeRates());
  const exchange = new ExchangeRateService(client, ttlMs);
  const item = makeItem();
  const itemService = makeItemService(item);
  const controller = new ItemController(itemService, exchange);
  return { client, fetchSpy, exchange, item, itemService, controller };
}

describe('UC-006 View prices in display currency', () => {
  it("REQ-005 AC1: A bidder who selects CHF, EUR or USD sees item prices and bids converted with a rate obtained from Frankfurter.", async () => {
    const { fetchSpy, controller } = makeSetup();
    const view = await controller.getItem('item-1', 'EUR');
    expect(fetchSpy).toHaveBeenCalled();
    expect(view.displayCurrency).toBe('EUR');
    expect(typeof view.convertedStartingPrice).toBe('number');
    expect(typeof view.convertedHighestBid).toBe('number');
  });

  it("REQ-005 AC2: Only CHF, EUR and USD are offered as display currencies.", async () => {
    const { controller } = makeSetup();
    expect(Object.values(Currency)).toEqual(['CHF', 'EUR', 'USD']);
    await expect(controller.getItem('item-1', 'GBP')).rejects.toThrow();
  });

  it("REQ-005 AC3: Converted prices are shown with the currency code.", async () => {
    const { controller } = makeSetup();
    const view = await controller.getItem('item-1', 'USD');
    expect(view.displayCurrency).toBe('USD');
    expect(view.convertedStartingPrice).not.toBeNull();
  });

  it("REQ-005 AC4: Conversion is for display only: stored bids and bid validation use the item currency.", async () => {
    const { controller, item, itemService } = makeSetup();
    const view = await controller.getItem('item-1', 'EUR');
    expect(itemService.getItem).toHaveBeenCalledWith('item-1');
    expect(view.item).toEqual(item);
    expect(view.item.currency).toBe('CHF');
  });

  it("REQ-010 AC1: Within 1 hour of a successful fetch, no further request is made to Frankfurter for the same rates.", async () => {
    vi.useFakeTimers({ toFake: ['Date'] });
    vi.setSystemTime(new Date('2030-01-01T00:00:00.000Z'));
    const { fetchSpy, controller } = makeSetup();
    await controller.getItem('item-1', 'EUR');
    vi.setSystemTime(new Date('2030-01-01T00:30:00.000Z'));
    await controller.getItem('item-1', 'USD');
    expect(fetchSpy).toHaveBeenCalledTimes(1);
  });

  it("REQ-010 AC2: After the cache is older than 1 hour, the next conversion fetches fresh rates.", async () => {
    vi.useFakeTimers({ toFake: ['Date'] });
    vi.setSystemTime(new Date('2030-01-01T00:00:00.000Z'));
    const { fetchSpy, controller } = makeSetup();
    await controller.getItem('item-1', 'EUR');
    expect(fetchSpy).toHaveBeenCalledTimes(1);
    vi.setSystemTime(new Date(Date.parse('2030-01-01T00:00:00.000Z') + ONE_HOUR_MS + 1000));
    await controller.getItem('item-1', 'EUR');
    expect(fetchSpy).toHaveBeenCalledTimes(2);
  });

  it("REQ-010 AC3: When Frankfurter cannot be reached and no valid cached rate exists, prices are shown only in the item currency and bidding still works.", async () => {
    const { fetchSpy, controller, item, itemService } = makeSetup();
    fetchSpy.mockRejectedValue(new Error('Frankfurter unavailable'));
    const view = await controller.getItem('item-1', 'EUR');
    expect(view.convertedStartingPrice).toBeNull();
    expect(view.convertedHighestBid).toBeNull();
    expect(view.item).toEqual(item);
    expect(itemService.getItem).toHaveBeenCalledWith('item-1');
  });

  it("SEQ-006 scenario: View prices in display currency", async () => {
    const { controller, itemService, fetchSpy } = makeSetup();
    const view = await controller.getItem('item-1', 'CHF');
    expect(itemService.getItem).toHaveBeenCalledWith('item-1');
    expect(fetchSpy).toHaveBeenCalledTimes(1);
    expect(view.item.id).toBe('item-1');
    expect(view.displayCurrency).toBe('CHF');
  });
});

import { describe, expect, it } from 'vitest';
import { LiveGateway } from '../src/live-updates/LiveGateway.js';
import { EventFeedClient } from '../src/live-updates/EventFeedClient.js';

type GatewaySockets = ConstructorParameters<typeof LiveGateway>[0];
type GatewaySocket = GatewaySockets extends Map<string, infer S> ? S : never;

function setup() {
  const sent: string[] = [];
  const socket = { send: (message: string) => { sent.push(message); } } as unknown as GatewaySocket;
  const sockets: GatewaySockets = new Map();
  sockets.set('client-1', socket);
  const liveGateway = new LiveGateway(sockets);
  const eventFeedClient = new EventFeedClient(liveGateway);
  return { sent, liveGateway, eventFeedClient };
}

describe('UC-004 Watch item live', () => {
  it.todo('REQ-007 AC1: manual: requires deploying two or more live update server instances and a multi-instance load setup, not practical as a unit test');

  it.todo('REQ-007 AC2: manual: requires deploying an additional instance and verifying no code change, a deployment-level check');

  it('SEQ-004 scenario: Watch item live', () => {
    const { sent, liveGateway, eventFeedClient } = setup();
    const payload = JSON.stringify({ itemId: 'item-1', amount: 25 });

    liveGateway.watch('client-1', 'item-1');
    eventFeedClient.onEvent('bid.accepted', payload);

    expect(sent.length).toBe(1);
    expect(sent[0]).toContain(payload);

    liveGateway.unwatch('client-1', 'item-1');
  });
});

