{
  "path": "test/UC-005.test.ts",
  "content": "import { describe, expect, it } from 'vitest';
import { DatabaseSync } from 'node:sqlite';
import { AuctionStatus } from '../src/auction-api/AuctionStatus.js';
import { Item } from '../src/auction-api/Item.js';
import { ItemStore } from '../src/auction-api/ItemStore.js';
import { ItemService } from '../src/auction-api/ItemService.js';
import { AuctionEventPublisher } from '../src/auction-api/AuctionEventPublisher.js';
import { AuctionCloser } from '../src/auction-api/AuctionCloser.js';

const endTime = new Date('2030-01-01T00:00:00Z');

function capturingFeed() {
  const published: Array<{ topic: string; payload: string }> = [];
  const feed = {
    publish(topic: string, payload: string) {
      published.push({ topic, payload });
    },
  };
  return { feed, published };
}

function setup() {
  const db = new DatabaseSync(':memory:');
  const itemStore = new ItemStore(db);
  const { feed, published } = capturingFeed();
  const publisher = new AuctionEventPublisher(feed as never);
  const itemService = new ItemService(itemStore, undefined as never, publisher);
  return { itemStore, itemService, published };
}

function openItem(id: string, highestBidderId: string | null, highestBidAmount: number | null) {
  return new Item(
    id,
    'seller-1',
    'Vintage lamp',
    10,
    'USD' as never,
    endTime,
    AuctionStatus.open,
    highestBidAmount,
    highestBidderId,
    null,
  );
}

describe('UC-005 Close auction', () => {
  it('REQ-004 AC1: At the end time the item no longer accepts bids.', async () => {
    const { itemStore, itemService } = setup();
    const item = openItem('item-1', 'bidder-1', 20);
    expect(item.isOpen(endTime)).toBe(false);
    await itemStore.saveItem(item);
    await itemService.closeDueAuctions(endTime);
    const stored = await itemStore.findItem('item-1');
    expect(stored).not.toBeNull();
    expect(stored!.status).not.toBe(AuctionStatus.open);
  });

  it('REQ-004 AC2: The bidder with the highest bid at the end time is recorded as the winner and the winning user sees on the item page that they won.', async () => {
    const { itemStore, itemService } = setup();
    await itemStore.saveItem(openItem('item-2', 'bidder-7', 50));
    await itemService.closeDueAuctions(endTime);
    const stored = await itemService.getItem('item-2');
    expect(stored.winnerId).toBe('bidder-7');
    expect(stored.status).toBe(AuctionStatus.closed);
  });

  it('REQ-004 AC3: Watchers of the item see the closed state and the winner.', async () => {
    const { itemStore, itemService, published } = setup();
    await itemStore.saveItem(openItem('item-3', 'bidder-9', 40));
    await itemService.closeDueAuctions(endTime);
    const closedEvent = published.find((e) => e.payload.includes('item-3'));
    expect(closedEvent).toBeDefined();
    expect(closedEvent!.payload).toContain('closed');
    expect(closedEvent!.payload).toContain('bidder-9');
  });

  it('REQ-004 AC4: An auction that ends with no bids is shown as unsold and has no winner.', async () => {
    const { itemStore, itemService } = setup();
    await itemStore.saveItem(openItem('item-4', null, null));
    await itemService.closeDueAuctions(endTime);
    const stored = await itemService.getItem('item-4');
    expect(stored.status).toBe(AuctionStatus.unsold);
    expect(stored.winnerId).toBeNull();
  });

  it('SEQ-005 scenario: Close auction', async () => {
    const { itemStore, itemService, published } = setup();
    await itemStore.saveItem(openItem('item-5', 'bidder-3', 30));
    const closer = new AuctionCloser(itemService, 1000);
    await closer.tick();
    const stored = await itemStore.findItem('item-5');
    expect(stored!.status).toBe(AuctionStatus.closed);
    expect(stored!.winnerId).toBe('bidder-3');
    expect(published.some((e) => e.payload.includes('item-5'))).toBe(true);
  });
});
"
}

