import { afterEach, describe, expect, it, vi } from 'vitest';
import { Currency } from '../src/auction-api/Currency.js';
import { ItemController } from '../src/auction-api/ItemController.js';
import { ItemService } from '../src/auction-api/ItemService.js';
import { ExchangeRateService } from '../src/exchange-rates/ExchangeRateService.js';
import { FrankfurterClient } from '../src/exchange-rates/FrankfurterClient.js';

const ONE_HOUR_MS = 60 * 60 * 1000;

afterEach(() => {
  vi.restoreAllMocks();
  vi.useRealTimers();
});

function makeItem(): Record<string, unknown> {
  return {
    id: 'item-1',
    sellerId: 'seller-1',
    title: 'Vintage clock',
    startingPrice: 100,
    highestBidAmount: 150,
    highestBidderId: 'bidder-1',
    winnerId: null,
    currency: 'CHF',
    endTime: new Date('2030-01-01T00:00:00.000Z'),
    status: 'open',
  };
}

function makeItemService(item: Record<string, unknown>): ItemService {
  return {
    getItem: vi.fn(async () => item),
    listItem: vi.fn(async () => item),
    listOpenItems: vi.fn(async () => [item]),
    closeDueAuctions: vi.fn(async () => undefined),
  } as unknown as ItemService;
}

function makeRates(): Record<string, number> {
  return { CHF: 1, EUR: 0.9, USD: 1.1 };
}

function makeSetup(ttlMs: number = ONE_HOUR_MS) {
  const client = new FrankfurterClient();
  const fetchSpy = vi.spyOn(client, 'fetchRates').mockResolvedValue(makeRates());
  const exchange = new ExchangeRateService(client, ttlMs);
  const item = makeItem();
  const itemService = makeItemService(item);
  const controller = new ItemController(itemService, exchange);
  return { client, fetchSpy, exchange, item, itemService, controller };
}

describe('UC-006 View prices in display currency', () => {
  it("REQ-005 AC1: A bidder who selects CHF, EUR or USD sees item prices and bids converted with a rate obtained from Frankfurter.", async () => {
    const { fetchSpy, controller } = makeSetup();
    const view = await controller.getItem('item-1', 'EUR');
    expect(fetchSpy).toHaveBeenCalled();
    expect(view.displayCurrency).toBe('EUR');
    expect(typeof view.convertedStartingPrice).toBe('number');
    expect(typeof view.convertedHighestBid).toBe('number');
  });

  it("REQ-005 AC2: Only CHF, EUR and USD are offered as display currencies.", async () => {
    const { controller } = makeSetup();
    expect(Object.values(Currency)).toEqual(['CHF', 'EUR', 'USD']);
    await expect(controller.getItem('item-1', 'GBP')).rejects.toThrow();
  });

  it("REQ-005 AC3: Converted prices are shown with the currency code.", async () => {
    const { controller } = makeSetup();
    const view = await controller.getItem('item-1', 'USD');
    expect(view.displayCurrency).toBe('USD');
    expect(view.convertedStartingPrice).not.toBeNull();
  });

  it("REQ-005 AC4: Conversion is for display only: stored bids and bid validation use the item currency.", async () => {
    const { controller, item, itemService } = makeSetup();
    const view = await controller.getItem('item-1', 'EUR');
    expect(itemService.getItem).toHaveBeenCalledWith('item-1');
    expect(view.item).toEqual(item);
    expect(view.item.currency).toBe('CHF');
  });

  it("REQ-010 AC1: Within 1 hour of a successful fetch, no further request is made to Frankfurter for the same rates.", async () => {
    vi.useFakeTimers({ toFake: ['Date'] });
    vi.setSystemTime(new Date('2030-01-01T00:00:00.000Z'));
    const { fetchSpy, controller } = makeSetup();
    await controller.getItem('item-1', 'EUR');
    vi.setSystemTime(new Date('2030-01-01T00:30:00.000Z'));
    await controller.getItem('item-1', 'USD');
    expect(fetchSpy).toHaveBeenCalledTimes(1);
  });

  it("REQ-010 AC2: After the cache is older than 1 hour, the next conversion fetches fresh rates.", async () => {
    vi.useFakeTimers({ toFake: ['Date'] });
    vi.setSystemTime(new Date('2030-01-01T00:00:00.000Z'));
    const { fetchSpy, controller } = makeSetup();
    await controller.getItem('item-1', 'EUR');
    expect(fetchSpy).toHaveBeenCalledTimes(1);
    vi.setSystemTime(new Date(Date.parse('2030-01-01T00:00:00.000Z') + ONE_HOUR_MS + 1000));
    await controller.getItem('item-1', 'EUR');
    expect(fetchSpy).toHaveBeenCalledTimes(2);
  });

  it("REQ-010 AC3: When Frankfurter cannot be reached and no valid cached rate exists, prices are shown only in the item currency and bidding still works.", async () => {
    const { fetchSpy, controller, item, itemService } = makeSetup();
    fetchSpy.mockRejectedValue(new Error('Frankfurter unavailable'));
    const view = await controller.getItem('item-1', 'EUR');
    expect(view.convertedStartingPrice).toBeNull();
    expect(view.convertedHighestBid).toBeNull();
    expect(view.item).toEqual(item);
    expect(itemService.getItem).toHaveBeenCalledWith('item-1');
  });

  it("SEQ-006 scenario: View prices in display currency", async () => {
    const { controller, itemService, fetchSpy } = makeSetup();
    const view = await controller.getItem('item-1', 'CHF');
    expect(itemService.getItem).toHaveBeenCalledWith('item-1');
    expect(fetchSpy).toHaveBeenCalledTimes(1);
    expect(view.item.id).toBe('item-1');
    expect(view.displayCurrency).toBe('CHF');
  });
});

